{
  "actions": [
    {
      "action": "Require valid source links before saving definitions",
      "mechanism": "Enforce source attachment in storage, so neither editor forms nor imports can create ungrounded definitions.",
      "implementation": "Require each definition to reference at least one existing supplied passage ID. Reject missing references and restrict deletion of referenced passages.",
      "check": "Attempt saves through forms and imports with absent, unknown, and valid passage IDs; only valid references should succeed.",
      "risk": "A valid reference does not establish that the passage supports the wording."
    },
    {
      "action": "Preserve wording through immutable definition revisions",
      "mechanism": "Append revisions rather than overwriting text, retaining the exact wording and source bindings of earlier definitions.",
      "implementation": "Store revision IDs, predecessor IDs, wording, and passage IDs. Make edits create new revisions; label older revisions without deleting them.",
      "check": "Revise a disputed definition twice; verify all three texts and their original source links remain inspectable.",
      "risk": "Revision history alone can conceal alternatives unless the interface exposes them."
    },
    {
      "action": "Represent disagreement as explicit competing definitions",
      "mechanism": "Separate competing claims from revision history, preventing editorial preference from erasing a live alternative.",
      "implementation": "Create dispute groups containing independently source-linked definition revisions. Record disagreement notes and editorial decisions separately; retain every competing text after resolution.",
      "check": "Mark one wording preferred, then resolve the dispute; confirm readers can still inspect every alternative and its source.",
      "risk": "A preferred label may appear authoritative; identify it as an editorial choice."
    },
    {
      "action": "Show definitions, passages, and disagreements together",
      "mechanism": "A contextual inspection view makes evidence and competing wording accessible without requiring readers to reconstruct their relationships.",
      "implementation": "Add an inspect control beside each definition that opens its supplied passages, passage IDs, and competing definitions with clear labels.",
      "check": "Using keyboard navigation, open a disputed entry and reach every competing wording and its complete linked passage.",
      "risk": "Truncated excerpts can obscure qualifications; always provide access to the full passage."
    },
    {
      "action": "Distinguish scoped meanings from direct contradictions",
      "mechanism": "Explicit applicability notes let different meanings coexist without automatically treating every wording difference as a conflict.",
      "implementation": "Add optional scope notes with supplied passage IDs. Let editors classify relationships as overlapping, distinct-scope, or disputed while preserving both definitions.",
      "check": "Create two scoped meanings and one disputed pair; verify classifications, wording, and supporting passages remain visible independently.",
      "risk": "Unsupported scope labels can manufacture agreement; allow readers to inspect their evidence."
    },
    {
      "action": "Keep competing definitions visible in search",
      "mechanism": "Term-level result grouping prevents ranking or deduplication from silently suppressing less-preferred definitions.",
      "implementation": "Index every retained wording. Group results by term, display alternative and dispute counts, and provide direct links to matching wording and passage IDs.",
      "check": "Search a phrase unique to a nonpreferred definition; confirm that wording is reachable and its competing definitions are disclosed.",
      "risk": "Large histories can overwhelm results; distinguish historical revisions from current alternatives."
    },
    {
      "action": "Export self-contained source-bound review snapshots",
      "mechanism": "Bundling definitions with supplied passages preserves inspectability when a reader lacks access to the editing application.",
      "implementation": "Generate a read-only HTML snapshot containing definition revisions, competing wording, disagreement notes, and passage-ID anchors with full supplied text.",
      "check": "Open the snapshot offline; follow every definition’s source links and verify each exported dispute includes all competing wording.",
      "risk": "Snapshots become stale; display their creation time and included revision IDs."
    }
  ],
  "abstention_reason": ""
}
